        return isinstance(x, (int, float)) and not isinstance(x, bool)

    depot = get_any(instance, ["depot", "depot_id", "start", "origin"], 0)
    capacity = get_any(instance, ["capacity", "vehicle_capacity", "cap"], None)

    coords = {}
    demand = {}

    customers = get_any(instance, ["customers", "nodes", "points", "locations"], None)
    if isinstance(customers, dict):
        for k, v in customers.items():
            coords[k] = get_any(v, ["coord", "coords", "position", "pos", "location"], None)
            demand[k] = get_any(v, ["demand", "load"], 0)
    elif isinstance(customers, list):
        for i, v in enumerate(customers):
            if isinstance(v, dict):
                cid = get_any(v, ["id", "node_id", "customer_id"], i)
                coords[cid] = get_any(v, ["coord", "coords", "position", "pos", "location"], None)
                demand[cid] = get_any(v, ["demand", "load"], 0)
            else:
                coords[i] = v
                demand[i] = 0

    if not coords:
        raw_coords = get_any(instance, ["coords", "coordinates", "xy", "points_by_id"], None)
        if isinstance(raw_coords, dict):
            for k, v in raw_coords.items():
                coords[k] = v
        elif isinstance(raw_coords, list):
            for i, v in enumerate(raw_coords):
                coords[i] = v

    if not demand:
        raw_demands = get_any(instance, ["demands", "loads"], None)
        if isinstance(raw_demands, dict):
            for k, v in raw_demands.items():
                demand[k] = v
        elif isinstance(raw_demands, list):
            for i, v in enumerate(raw_demands):
                demand[i] = v

    if capacity is None:
        if isinstance(instance, dict):
            for k in ("capacity", "vehicle_capacity", "cap"):
                if k in instance and is_num(instance[k]):
                    capacity = instance[k]
                    break
    if capacity is None:
        capacity = 10**18

    all_ids = set(coords.keys()) | set(demand.keys())
    if depot in all_ids:
        all_ids.remove(depot)
    if not all_ids:
        return []

    for cid in list(all_ids):
        if cid not in demand:
            demand[cid] = 0

    def dist(a, b):
        ca = coords.get(a)
        cb = coords.get(b)
        if ca is None or cb is None:
            return 0.0 if a == b else 1.0
        ax, ay = ca[0], ca[1]
        bx, by = cb[0], cb[1]
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    customers_list = list(all_ids)
    if depot in coords and all(c in coords for c in customers_list):
        dx0, dy0 = coords[depot][0], coords[depot][1]

        def angle_key(cid):
            x = coords[cid][0] - dx0
            y = coords[cid][1] - dy0
            if x == 0 and y == 0:
                return (0, 0.0, cid)
            if x >= 0 and y >= 0:
                q = 0
            elif x < 0 <= y:
                q = 1
            elif x < 0 and y < 0:
                q = 2
            else:
                q = 3
            slope = y / x if x != 0 else (10**18 if y >= 0 else -10**18)
            return (q, slope, cid)

        customers_list.sort(key=angle_key)
    else:
        customers_list.sort()

    def route_load(route):
        s = 0
        for c in route:
            s += demand.get(c, 0)
        return s

    def route_cost(route):
        if not route:
            return 0.0
        c = dist(depot, route[0]) + dist(route[-1], depot)
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1])
        return c

    def two_opt(route):
        if len(route) < 4:
            return route[:]
        best = route[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            n = len(best)
            for i in range(n - 2):
                for j in range(i + 2, n):
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    cc = route_cost(cand)
                    if cc + 1e-12 < best_cost:
                        best = cand
                        best_cost = cc
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = []
    unserved = customers_list[:]

    while unserved:
        feasible = [c for c in unserved if demand.get(c, 0) <= capacity]
        if not feasible:
            routes.append([unserved.pop(0)])
            continue

        seed = min(feasible, key=lambda c: (dist(depot, c), -demand.get(c, 0), c))
        route = [seed]
        load = demand.get(seed, 0)
        unserved.remove(seed)
        current = seed

        while True:
            candidates = [c for c in unserved if load + demand.get(c, 0) <= capacity]
            if not candidates:
                break
            best = None
            best_key = None
            for c in candidates:
                d = dist(current, c)
                gain = dist(depot, current) + d + dist(c, depot) - dist(depot, current) - dist(depot, c)
                key = (d, -demand.get(c, 0), gain, c)
                if best is None or key < best_key:
                    best = c
                    best_key = key
            route.append(best)
            load += demand.get(best, 0)
            unserved.remove(best)
            current = best

        route = two_opt(route)
        routes.append(route)

    # Repair / merge pass: try to reduce route count by moving customers into slack.
    changed = True
    while changed:
        changed = False
        routes.sort(key=lambda r: (len(r), route_cost(r), r))
        i = 0
        while i < len(routes):
            r = routes[i]
            if not r:
                routes.pop(i)
                changed = True
                continue
            load_r = route_load(r)
            moved = False
            for idx, c in enumerate(r):
                dem_c = demand.get(c, 0)
                for j in range(len(routes)):
                    if j == i:
                        continue
                    s = routes[j]
                    if route_load(s) + dem_c > capacity:
                        continue
                    best_pos = None
                    best_delta = None
                    base_s = route_cost(s)
                    for p in range(len(s) + 1):
                        cand_s = s[:p] + [c] + s[p:]
                        delta = route_cost(cand_s) - base_s
                        if best_delta is None or delta < best_delta:
                            best_delta = delta
                            best_pos = p
                    # remove c from r and see if feasible/cost-improving
                    cand_r = r[:idx] + r[idx + 1:]
                    if cand_r:
                        cand_r = two_opt(cand_r)
                    new_cost = route_cost(cand_r) + route_cost(s[:best_pos] + [c] + s[best_pos:])
                    old_cost = route_cost(r) + route_cost(s)
                    if new_cost + 1e-12 < old_cost:
                        routes[j] = s[:best_pos] + [c] + s[best_pos:]
                        if cand_r:
                            routes[i] = cand_r
                        else:
                            routes.pop(i)
                            changed = True
                            moved = True
                        routes[j] = two_opt(routes[j])
                        changed = True
                        moved = True
                        break
                if moved:
                    break
            if not moved:
                i += 1

    # Final local search: relocate and swap within/between routes for cost improvement.
    improved = True
    while improved:
        improved = False
        for i in range(len(routes)):
            routes[i] = two_opt(routes[i])

        for i in range(len(routes)):
            if improved:
                break
            r = routes[i]
            for idx, c in enumerate(r):
                dem_c = demand.get(c, 0)
                for j in range(len(routes)):
                    s = routes[j]
                    for p in range(len(s) + 1):
                        if i != j and route_load(s) + dem_c > capacity:
                            continue
                        if i == j and (p == idx or p == idx + 1):
                            continue
                        if i == j:
                            cand = r[:idx] + r[idx + 1:]
                            cand2 = cand[:p] + [c] + cand[p:]
                            if route_cost(cand2) + 1e-12 < route_cost(r):
                                routes[i] = two_opt(cand2)
                                improved = True
                                break
                        else:
                            cand_r = r[:idx] + r[idx + 1:]
                            cand_s = s[:p] + [c] + s[p:]
                            if route_cost(cand_r) + route_cost(cand_s) + 1e-12 < route_cost(r) + route_cost(s):
                                if cand_r:
                                    routes[i] = two_opt(cand_r)
                                else:
                                    routes.pop(i)
                                routes[j if j < i else j - (1 if cand_r == [] and j > i else 0)] = two_opt(cand_s)
                                improved = True
                                break
                    if improved:
                        break
                if improved:
                    break

    # Clean empty routes and ensure determinism.
    routes = [r for r in routes if r]
    routes.sort(key=lambda r: (r[0], len(r), r))
    return routes
